  const KUNUT1 = "Allâhümme innâ nesteînüke ve nestağfirüke ve nestehdîk. Ve nü'minü bike ve netûbü ileyk. Ve netevekkelü aleyke ve nüsnî aleykel-hayra küllehû neşkürüke ve lâ nekfürüke ve nahleu ve netrükü men yefcürük.";
  const KUNUT1A = "Allah'ım! Ancak senden yardım isteriz, günahlarımızı bağışlamanı isteriz, razı olduğun şeylere hidayet etmeni (doğru yolu göstermeni) isteriz. Sana inanırız, sana tövbe ederiz. Sana güveniriz. Bize verdiğin bütün nimetleri bilerek seni hayır ile överiz. Sana şükrederiz. Hiçbir nimetini inkâr etmeyiz (nankörlük etmeyiz). Sana karşı geleni bırakırız, ondan ayrılırız.";
  const KUNUT2 = "Allâhümme iyyâke na'büdü ve leke nüsallî ve nescüdü ve ileyke nes'â ve nahfidü nercû rahmeteke ve nahşâ azâbeke inne azâbeke bil-küffâri mülhık.";
  const KUNUT2A = "Allah'ım! Yalnız sana kulluk ederiz. Namazı yalnız senin için kılarız ve yalnız sana secde ederiz. Yalnız sana koşar ve sana yaklaştıracak ibadetleri yapmaya çalışırız. Rahmetini umarız, azabından korkarız. Şüphesiz senin azabın kâfirlere ulaşır.";

