  /* =============================== 4. ÜNİTE: PEYGAMBERLİĞİNDEN ÖNCE HZ. MUHAMMED =============================== */

  /* Arap Yarımadası ve kervan yolları (şematik). harf: şehir adları yerine harf göster */
  function arabistan(harf) {
    const yerler = [["Şam", 230, 34, "K"], ["Medine", 190, 150, "L"], ["Mekke", 205, 222, "M"], ["Taif", 250, 232, "N"], ["Yemen", 270, 330, "P"]];
    let ic = `<polygon class="g-yumusak g-cizgi" points="150,60 330,70 470,190 500,260 430,330 330,365 250,350 205,280 165,180" stroke-width="2"/>`;
    ic += G.yazi(110, 250, "Kızıldeniz", { k: 1 }) + G.yazi(470, 120, "Basra Körfezi", { k: 1 }) + G.yazi(370, 220, "ARAP", { b: 1 }) + G.yazi(370, 240, "YARIMADASI", { b: 1 });
    ic += G.ok(205, 210, 192, 160, "g-cizgi") + G.ok(190, 140, 228, 46, "g-cizgi") + G.ok(214, 234, 262, 318, "g-cizgi");
    yerler.forEach(([ad, x, y, h]) => { ic += `<circle class="g-d" cx="${x}" cy="${y}" r="6"/>` + G.yazi(x - 12, y + 4, harf ? h : ad, { a: "end", b: 1 }); });
    ic += G.yazi(320, 395, "Oklar: kervan yolları (şematik çizim)", { k: 1 });
    return G.svg(560, 405, ic, "Arap Yarımadası ve kervan yolları");
  }

