    anlatim: [
      { baslik: "Dinî edebiyat türleri",
        metin: "Şairlerimiz inançlarını, Allah ve Peygamber sevgilerini şiirlerine yansıtmış; böylece dinî edebiyat türleri ortaya çıkmıştır:<br>• <b>Tevhit:</b> Allah'ın birliğini ve yüceliğini anlatan şiir<br>• <b>Münacat:</b> Allah'a yalvarıp dua etmek amacıyla yazılan şiir<br>• <b>Naat:</b> Hz. Peygamber'i övmek için yazılan şiir<br>• <b>Mevlit:</b> Hz. Peygamber'in doğumunu ve hayatını anlatan manzum eser<br>• <b>Hilye:</b> Hz. Peygamber'in dış görünüşünü ve güzel ahlakını anlatan eser<br>• <b>İlahi:</b> Allah sevgisini ve dinî duyguları anlatan, bestelenerek okunan şiir",
        ornek: "Bir şair Allah'tan af dileyip O'na yalvardığı bir şiir yazarsa münacat; Hz. Peygamber'e olan sevgisini anlatıp onu övdüğü bir şiir yazarsa naat yazmış olur.",
        gorsel: G.tablo(["Tür", "Konusu"], [["Tevhit", "Allah'ın birliği ve yüceliği"], ["Münacat", "Allah'a yalvarma, dua"], ["Naat", "Hz. Peygamber'i övme"], ["Mevlit", "Hz. Peygamber'in doğumu ve hayatı"], ["Hilye", "Hz. Peygamber'in görünüşü ve ahlakı"], ["İlahi", "Allah sevgisi; bestelenerek okunur"]]),
        durak: { soru: "Hz. Peygamber'i övmek için yazılan şiirlere ne ad verilir?", secenekler: [
          ["Naat", true, "Hz. Peygamber'i öven şiirlere naat denir."],
          ["Münacat", false, "Münacat Allah'a yalvarma şiiridir."],
          ["Tevhit", false, "Tevhit Allah'ın birliğini anlatan şiirdir."],
          ["Mahya", false, "Mahya minareler arasına asılan ışıklı yazıdır."]] } },
      { baslik: "Yunus Emre ve ilahiler",
        metin: "<b>Yunus Emre</b>, 13. yüzyılın sonu ile 14. yüzyılın başında Anadolu'da yaşamış büyük bir halk şairidir. Şiirlerini halkın anlayacağı sade bir <b>Türkçeyle</b> yazmıştır. Şiirlerinde Allah sevgisini, insan sevgisini, hoşgörüyü ve dünyanın geçiciliğini anlatır. Pek çok şiiri <b>ilahi</b> olarak bestelenmiş ve günümüze kadar okunmuştur.<br>Yunus Emre'nin sevgi dolu çağrısı şöyledir: “Gelin tanış olalım / İşi kolay kılalım / Sevelim sevilelim / Dünya kimseye kalmaz”",
        ornek: "Yunus Emre'nin “Dolap niçin inlersin / Derdim vardır inlerim” dizeleriyle başlayan şiiri, bugün de ilahi olarak okunmaktadır.",
        durak: { soru: "Yunus Emre'nin “Sevelim sevilelim / Dünya kimseye kalmaz” dizelerinde öne çıkan değer hangisidir?", secenekler: [
          ["Sevgi ve kardeşlik", true, "Dizeler insanları birbirini sevmeye çağırır."],
          ["Zenginlik", false, "Dizeler dünyanın geçiciliğini vurgular; zenginliği değil."],
          ["Rekabet", false, "Dizelerde yarışma değil, sevgi vardır."],
          ["Öfke", false, "Dizelerde öfke değil, sevgi vardır."]] } },
      { baslik: "Mevlid ve Süleyman Çelebi",
        metin: "<b>Süleyman Çelebi</b>, 1409 yılında Bursa'da <b>“Vesîletü'n-Necât”</b> adlı eserini yazmıştır. Bu eser halk arasında <b>“Mevlid”</b> olarak bilinir. Eserde Hz. Peygamber'in doğumu, hayatı, mucizeleri ve vefatı anlatılır.<br>Mevlid şöyle başlar: “Allah adın zikredelim evvelâ / Vâcib oldur cümle işte her kula” (Önce Allah'ın adını analım; her işte bu, her kula gereklidir.)<br>Mevlid; doğum, sünnet, asker uğurlama ve vefat gibi pek çok vesileyle okunur.",
        ornek: "Kandil gecelerinde camilerde Mevlid okunduğunu duymuş olabilirsin.",
        durak: { soru: "“Vesîletü'n-Necât” (Mevlid) adlı eserin yazarı kimdir?", secenekler: [
          ["Süleyman Çelebi", true, "Mevlid'i 1409'da Bursa'da Süleyman Çelebi yazmıştır."],
          ["Yunus Emre", false, "Yunus Emre ilahileriyle tanınır."],
          ["Fuzuli", false, "Fuzuli Su Kasidesi ile tanınır."],
          ["Mehmet Âkif Ersoy", false, "Mehmet Âkif Ersoy İstiklal Marşı'nın ve Safahat'ın şairidir."]] } },
      { baslik: "Diğer önemli eserler",
        metin: "• <b>Kutadgu Bilig:</b> Yusuf Has Hacib'in Karahanlılar döneminde yazdığı, mutluluğa ulaştıran bilgiyi anlatan, dinî ve ahlaki öğütler içeren eser<br>• <b>Divan-ı Hikmet:</b> Hoca Ahmet Yesevi'nin dinî ve ahlaki öğütler içeren şiirleri (hikmetler)<br>• <b>Su Kasidesi:</b> Fuzuli'nin Hz. Peygamber'i övdüğü ünlü naatı<br>• <b>Hilye-i Hâkânî:</b> Hâkânî Mehmed Bey'in Hz. Peygamber'in özelliklerini anlattığı manzum hilye<br>• <b>Mesnevi:</b> Mevlana Celaleddin-i Rumi'nin hikâyelerle öğütler verdiği eser<br>• <b>Safahat:</b> Mehmet Âkif Ersoy'un şiirleri; dinî ve millî değerler önemli yer tutar",
        ornek: "Fuzuli, Su Kasidesi'nde Hz. Peygamber'e duyduğu sevgiyi “su” sözcüğü etrafında anlatır.",
        durak: { soru: "Fuzuli'nin Hz. Peygamber'i övdüğü ünlü eseri hangisidir?", secenekler: [
          ["Su Kasidesi", true, "Su Kasidesi Fuzuli'nin ünlü naatıdır."],
          ["Kutadgu Bilig", false, "Kutadgu Bilig Yusuf Has Hacib'in eseridir."],
          ["Mesnevi", false, "Mesnevi Mevlana'nın eseridir."],
          ["Safahat", false, "Safahat Mehmet Âkif Ersoy'un eseridir."]] } },
    ],
